choices = payload.get("choices") or []
if not choices:
    continue
choice = choices[0] or {}
if choice.get("finish_reason"):
    finish_reason = choice["finish_reason"]

delta = choice.get("delta") or {}

# cycle-129 FR-7 (D-7.3): a local reasoning model streams its trace as
# `delta.reasoning_content` before any content. It keeps the recovery
# tracker alive (first-token deadline) but is never fed to the content
# state machine and never reaches `content`; it lands in `thinking`.
for _rkey in REASONING_DELTA_KEYS:
    _rtext = delta.get(_rkey)
    if isinstance(_rtext, str) and _rtext:
        recovery_tracker.on_progress(now_provider())
        accumulate_capped(
            reasoning_parts, _rtext, cap=MAX_TEXT_PART_BYTES, kind="reasoning"
        )

# Text content
content = delta.get("content")
if content is not None:
    # cycle-113 T2.2: feed tracker on content deltas (incl. empty
    # strings per SDD §2.1). Refusal text is also visible content
    # and gets the same treatment below.
    _recovery_feed_openai(
        recovery_tracker, content, partial_text_seen,
        config_applied, now_provider,
    )
    if content:
        accumulate_capped(
            text_parts, content, cap=MAX_TEXT_PART_BYTES, kind="text"
        )

# Refusal (Responses API style; rare on /chat/completions but possible)
refusal = delta.get("refusal")
if refusal is not None:
    _recovery_feed_openai(
        recovery_tracker, refusal, partial_text_seen,
        config_applied, now_provider,
    )
    if refusal:
        accumulate_capped(
            text_parts, refusal, cap=MAX_TEXT_PART_BYTES, kind="refusal"
        )

# Tool calls. cycle-113 T2.2: function.arguments deltas are
# intentionally NOT fed to the recovery tracker per SDD §3.3 —
# tool-only responses are legitimately empty-content but never
# KF-002 failures; feeding json_delta would confuse the
# empty_content_window detector.
for tc in delta.get("tool_calls", []) or []:
    idx = tc.get("index", 0)
    entry = tool_calls_by_index.setdefault(
        idx, {"id": "", "name": "", "arguments_parts": []}
    )
    if tc.get("id"):
        entry["id"] = tc["id"]
    fn = tc.get("function") or {}
    if fn.get("name"):
        entry["name"] = fn["name"]
    if fn.get("arguments") is not None:
        accumulate_capped(
            entry["arguments_parts"],
            fn["arguments"],
            cap=MAX_ARGS_PART_BYTES,
            kind="arguments",
        )

        "refusal_parts": [],
        "arguments_parts": [],
        "summary_text_parts": [],
    }
    if item_type in ("function_call", "tool_call"):
        entry["call_id"] = item.get("call_id") or item.get("id", "")
        entry["name"] = item.get("name", "")
        # Sometimes initial `arguments` is present (rare).
        init_args = item.get("arguments")
        if init_args:
            accumulate_capped(
                entry["arguments_parts"],
                init_args,
                cap=MAX_ARGS_PART_BYTES,
                kind="arguments",
            )
    items_by_id[item_id] = entry

elif ev_type == "response.output_text.delta":
    item_id = data.get("item_id")
    delta_text = data.get("delta", "") or ""
    # cycle-113 T2.3: feed tracker on output_text.delta per SDD §3.3.
    _recovery_feed_openai(
        recovery_tracker, delta_text, partial_text_seen,
        config_applied, now_provider,
    )
    if item_id and item_id in items_by_id:
        accumulate_capped(
            items_by_id[item_id]["text_parts"],
            delta_text,
            cap=MAX_TEXT_PART_BYTES,
            kind="text",
        )

elif ev_type == "response.refusal.delta":
    item_id = data.get("item_id")

